#include <vector>
#include <queue>
#include <unordered_set>

class Solution {
public:
    bool validateBinaryTreeNodes(int n, std::vector<int>& leftChild, std::vector<int>& rightChild) {
        std::vector<int> inDegree(n, 0);
        for (int i = 0; i < n; ++i) {
            for (int c : {leftChild[i], rightChild[i]}) {
                if (c != -1) {
                    if (++inDegree[c] > 1) return false;
                }
            }
        }
        int root = -1;
        for (int i = 0; i < n; ++i) {
            if (inDegree[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;
        std::queue<int> q;
        q.push(root);
        std::vector<bool> visited(n, false);
        int count = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (visited[u]) return false;
            visited[u] = true;
            count++;
            for (int c : {leftChild[u], rightChild[u]}) {
                if (c != -1) q.push(c);
            }
        }
        return count == n;
    }
};

import java.util.*;

class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] inDegree = new int[n];
        for (int i = 0; i < n; i++) {
            int[] children = {leftChild[i], rightChild[i]};
            for (int c : children) {
                if (c != -1) {
                    if (++inDegree[c] > 1) return false;
                }
            }
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;
        Queue<Integer> q = new LinkedList<>();
        q.offer(root);
        boolean[] visited = new boolean[n];
        int count = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (visited[u]) return false;
            visited[u] = true;
            count++;
            for (int c : new int[]{leftChild[u], rightChild[u]}) {
                if (c != -1) q.offer(c);
            }
        }
        return count == n;
    }
}

var validateBinaryTreeNodes = function(n, leftChild, rightChild) {
    const inDegree = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        for (const c of [leftChild[i], rightChild[i]]) {
            if (c !== -1) {
                inDegree[c]++;
                if (inDegree[c] > 1) return false;
            }
        }
    }
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (inDegree[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }
    if (root === -1) return false;
    const q = [root];
    const visited = new Uint8Array(n);
    let head = 0, count = 0;
    while (head < q.length) {
        const u = q[head++];
        if (visited[u]) return false;
        visited[u] = 1;
        count++;
        for (const c of [leftChild[u], rightChild[u]]) {
            if (c !== -1) q.push(c);
        }
    }
    return count === n;
};
